// === Tab: mySketch ===
// For the #WCCChallenge, theme: "illusion."
// This recreates Victoria Skye's “Skye Blue Café Wall Illusion ”
// https://illusionoftheyear.com/2017/10/skye-blue-cafe-wall-illusion/

let illusion = true;
let c1, c2, c3;
let sa = 0;
let rows = [3,4,7,8]

function setup() {
	createCanvas(windowWidth, windowHeight);
	if (width < 2.038216560509554 * height) width = 2.038216560509554 * height;
	else height = (1 / 2.038216560509554) * width;
	c1 = color(random(50, 100), random(50, 100), random(50, 100));
	c2 = color(red(window.color(c1)) * 2, green(window.color(c1)) * 2, blue(window.color(c1)) * 2);
	c3 = color(red(window.color(c1)) * 1.5, green(window.color(c1)) * 1.5, blue(window.color(c1)) * 1.5);
}

function draw() {
	sa = lerp(sa, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), windowWidth / 4, 3 * windowWidth / 4, -1, 1, true), 0.1);
	background(0);
	noStroke();
	rectMode(CORNER);
	strokeWeight(2);
	for (let col = 0; col < 7; col++) {
		let x = width / 28 + col * width / 7;
		fill(c2);
		rect(x, 0, width / 14, height);
	}
	for (let row = 0; row < 5; row++) {
		let y = height / 20 + row * height / 5;
		fill(c1);
		rect(0, y, width, height / 10);
	}
	if (!illusion) return;
	rectMode(CENTER);
	for (let col = 0; col <= 14; col++) {
		for (let row = 0; row <= 10; row++) {
			let x = -width / 28 + col * width / 14;
			let y = -height / 20 + row * height / 10;
			push();
			translate(x, y);
			if (row%2== col%2) rotate(-sa * QUARTER_PI);
			else rotate(sa * QUARTER_PI);
			if(rows.includes(row)) rotate(HALF_PI);
			fill(c2);
			rect(height / 90, -height / 90, height / 45);
			rect(-height / 90, height / 90, height / 45);
			fill(0);
			rect(-height / 90, -height / 90, height / 45);
			rect(height / 90, height / 90, height / 45);
			pop();
			if (row % 2 == 1 && col % 2 == 0) {
				push();
				translate(x, y);
				translate(width / 28, height / 20);
				if (row % 4 == 1) {
					shearX(sa * PI / 12);
				} else {
					shearX(-sa * PI / 12);
				}
				fill(c2);
				scale(1.5);
				beginShape();
				vertex(-height / 45, 0);
				vertex(-height / 90, -height / 90);
				vertex(height / 90, -height / 90);
				vertex(height / 45, 0);
				vertex(height / 90, height / 90);
				vertex(-height / 90, height / 90);
				endShape(CLOSE);
				stroke(c3);
				strokeWeight(2);
				noFill();
				if (row % 4 != 1) {
					curve(height / 45, -sa * height / 20,   height / 45, 0, width / 26, sa * height / 280,       width / 26, -sa * height / 25);
					curve(-height / 45, sa * height / 20,   -height / 45, 0, -width / 26, -sa * height / 280,     -width / 26, sa * height / 25);
				} else {
					curve(height / 45, sa * height / 20,   height / 45, 0, width / 26, -sa * height / 280,      width / 26, sa * height / 25);
					curve(-height / 45, -sa * height / 20,   -height / 45, 0, -width / 26, sa * height / 280,     -width / 26, -sa * height / 25);
				}
				noStroke();
				scale(0.5);
				fill(255);
				beginShape();
				vertex(-height / 45, 0);
				vertex(-height / 90, -height / 90);
				vertex(height / 90, -height / 90);
				vertex(height / 45, 0);
				vertex(height / 90, height / 90);
				vertex(-height / 90, height / 90);
				endShape(CLOSE);
				pop();
			}
			if (row % 2 == 0 && col % 2 == 1) {
				let shift = 1 - 2 * (row % 4)
				push();
				translate(x, y);
				translate(width / 28, height / 20);
				rotate(HALF_PI);
				fill(c3);
				scale(1.8, 1.5);
				if (row % 4 == 0) {
					beginShape();
					vertex(-height / 45, 0);
					vertex(-height / 90, -height / 90 + sa * height / 720);
					vertex(height / 90, -height / 90 + sa * height / 720);
					vertex(height / 45, 0);
					vertex(height / 90, height / 90 + sa * height / 720);
					vertex(-height / 90, height / 90 + sa * height / 720);
					endShape(CLOSE);
					stroke(c3)
					line(height / 45, 0, height / 32, -sa * height / 360);
					line(-height / 45, 0, -height / 32, -sa * height / 360);
				} else {
					beginShape();
					vertex(-height / 45, 0);
					vertex(-height / 90, -height / 90 - sa * height / 720);
					vertex(height / 90, -height / 90 - sa * height / 720);
					vertex(height / 45, 0);
					vertex(height / 90, height / 90 - sa * height / 720);
					vertex(-height / 90, height / 90 - sa * height / 720);
					endShape(CLOSE);
					stroke(c3)
					line(height / 45, 0, height / 32, sa * height / 360);
					line(-height / 45, 0, -height / 32, sa * height / 360);
				}
				stroke(c3);
				strokeWeight(2);

				noStroke();
				scale(0.5,0.4);
				fill(255);
				if (row % 4 == 0) translate(0, sa * height / 240);
				else translate(0, -sa * height / 240);
				beginShape();
				vertex(-height / 45, 0);
				vertex(-height / 90, -height / 90);
				vertex(height / 90, -height / 90);
				vertex(height / 45, 0);
				vertex(height / 90, height / 90);
				vertex(-height / 90, height / 90);
				endShape(CLOSE);
				pop();
			}
			push();
			translate(x, y);
			translate(width / 28, height / 20);
			if (row % 4 == 1) {
				rotate(sa * PI / 18);
			} else {
				rotate(-sa * PI / 18);
			}
			rotate(QUARTER_PI);
			if (col % 2 == 1 && row % 2 == 1) {
				beginClip({
					invert: true
				});
				ellipse(-height / 30, 0, height / 90, height / 15);
				ellipse(height / 30, 0, height / 90, height / 15);
				ellipse(0, -height / 30, height / 15, height / 90, );
				ellipse(0, height / 30, height / 15, height / 90, );

				endClip();
				fill(c3);
				rect(0, 0, height / 15);
				fill(255);
				rect(0, 0, height / 30);
				fill(c3);
				rect(0, 0, height / 60);
			}
			pop();
		}
	}
}

function mousePressed() {
	illusion = !illusion;
	if (illusion) {
		c1 = color(random(50, 100), random(50, 100), random(50, 100));
		c2 = color(red(window.color(c1)) * 2, green(window.color(c1)) * 2, blue(window.color(c1)) * 2);
		c3 = color(red(window.color(c1)) * 1.5, green(window.color(c1)) * 1.5, blue(window.color(c1)) * 1.5);
	}
}
